sys.path.insert(0,'/app/output');import kinematics as k
q=np.load('/app/output/q.npy')
for t in [(0,.35,-.2),(-.15,.4,-.1),(-.3,.4,.1),(-.35,.25,.2)]:
 best=None
 for j in range(10):
  v=q.copy();v[11:16]=np.random.default_rng(j).uniform([-2,-.1,-1,-1,-.1],[2,2,4,2.5,1.5]);v,p,l=k.ik(v,'lh',np.array(t))
  err=np.linalg.norm(p-t)
  if best is None or err<best[0]:best=(err,v,p)
 print(t,best[0],best[2],np.round(best[1][11:18],2))
 if t==(-.3,.4,.1):np.save('/app/output/support.npy',best[1])
